<script setup lang="ts">import{computed}from'vue';import{useRoute}from'vue-router';import{chapters}from'../data/chapters';import{useAppStore}from'../stores/app';import{Sparkles,Heart,ShieldCheck,Bookmark,RotateCcw,Home}from'@lucide/vue';const route=useRoute(),store=useAppStore();const id=Number(route.params.id);const chapter=computed(()=>chapters.find(c=>c.id===id)!);const result=computed(()=>store.s.answers[id]);const reviewId=computed(()=>result.value?.choice.id||'')</script>
<template><section v-if="result" class="page result"><div class="clear"><Sparkles/><small>CHAPTER {{id}} COMPLETE</small><h1>Nice work, {{store.s.name}}!</h1><p>今日も一歩、英語とエマに近づきました。</p><div class="xp">+{{result.choice.englishXp}} <small>ENGLISH XP</small></div></div><div class="reaction"><img src="/assets/emma.png"/><div><b>Emma</b><p>“{{result.choice.heroineResponse}}”</p><small>{{result.choice.heroineResponseJa}}</small></div></div><div class="delta"><span><Heart/> Affection <b :class="{minus:result.choice.affectionChange<0}">{{result.choice.affectionChange>0?'+':''}}{{result.choice.affectionChange}}</b></span><span><ShieldCheck/> Trust <b :class="{minus:result.choice.trustChange<0}">{{result.choice.trustChange>0?'+':''}}{{result.choice.trustChange}}</b></span></div><div class="card lesson"><p class="eyebrow">TODAY'S REVIEW</p><label>あなたの回答</label><h3>“{{result.choice.englishText}}”</h3><label>より自然な表現</label><h3 class="natural">“{{result.choice.naturalExpression}}”</h3><p>{{result.choice.explanation}}</p><div class="impression"><b>エマへの印象</b>{{result.choice.feedback}}</div></div><div class="card words"><h3>覚えておきたい言葉</h3><span v-for="w in chapter.words">{{w}}</span></div><button class="secondary" @click="store.toggleReview(reviewId)"><Bookmark :fill="store.s.reviews.includes(reviewId)?'currentColor':'none'"/>{{store.s.reviews.includes(reviewId)?'復習リストに追加済み':'復習リストに追加'}}</button><RouterLink class="primary" :to="`/conversation/${id}`"><RotateCcw/>もう一度プレイ</RouterLink><RouterLink class="text-link" to="/home"><Home/>ホームへ戻る</RouterLink></section></template>
